import React, { useEffect, useState, useRef } from 'react';
import './Research.css';
import AnimatedCounter from './AnimatedCounter';

const Research = ({ language }) => {
  const [animateCharts, setAnimateCharts] = useState(false);
  const [animateDonut, setAnimateDonut] = useState(false);
  const sectionRef = useRef(null);

  const publicUrl = process.env.PUBLIC_URL || '';

  const content = {
    RU: {
      title: 'О проекте / Исследование',
      intro: [
        'Мы - студенты Тюменского Государственного Университета. И мы решили разобраться, что на самом деле думают о Тюмени иностранные студенты.',
        'Зачем это нам? Во-первых, самим интересно. Во-вторых, стереотипы о Сибири - это не шутки. «Там холодно, опасно, делать нечего» — такие мысли реально мешают людям сюда ехать. А значит, страна теряет талантливых ребят, которые могли бы здесь остаться и работать, а иностранцы ограничивают себя от поездки в хороший город.',
        'Мы опросили 137 иностранных студентов нашего университета. Из Казахстана, Узбекистана, Греции, Азербайджана, Китая и других стран. Спрашивали: что знали до приезда, чего боялись, что увидели на самом деле и посоветовали бы друзьям.',
        'Анкета была не только с галочками, но и с открытыми вопросами. Поэтому у нас много живых цитат, иногда смешных, иногда очень честных. Кто-то написал про «столицу деревень», кто-то - «открытые люди», а один парень из Казахстана спросил: «За ответ балл получу по орг?»'
      ],
      findingsTitle: 'Что выяснили',
      findings: [
        'Главная цифра — 80%. Столько опрошенных сказали, что их ожидания от Тюмени оправдались или были превзойдены. В социологии это очень сильный результат.',
        'До приезда почти никто ничего не знал про историю и архитектуру города. Даже про то, что здесь когда‑то лежал Ленин, знает единица. Вместо фактов - стереотипы: суровый холод, глухая деревня, злые люди.',
        'Больше всего боялись именно холода. «В п***у, там -40, я замерзну» — прямо так и писали. Ещё боялись, что не примут, что будут проблемы с общагой и документами.',
        'А оказалось, что город современный и чистый. Набережная, нормальные дороги, красивые здания. Люди открытые, помогают. Даже климат не подвёл: средняя температура зимой около -17, а не -40. И летом вполне себе +25.',
        'Если копнуть глубже, видно три совершенно разных типа студентов.'
      ],
      types: [
        { title: 'Казахстанцы (55 человек)', desc: 'Самая спокойная и адаптированная группа. Приезжают без культурного шока, главное для них — чистота и порядок. В Тюмени они находят то, что ищут.' },
        { title: 'Узбекистанцы (24 человека)', desc: 'Чаще всего едут к родственникам. Для них Тюмень — это про деньги, работу и дорогие документы. Им нужна конкретная помощь: с жильём, с оформлением, с деньгами.' },
        { title: 'Европа и москвичи (58 человек)', desc: 'Привозят с собой стереотип «деревни». Сначала смотрят свысока, а потом искренне удивляются, что Тюмень — нормальный современный город. Им нужно показывать архитектуру, культуру, нормальную городскую жизнь. С ними работает не статистика, а личный опыт.' }
      ],
      donutTitle: 'Откуда узнают о Тюмени',
      donutText: [
        'Самый главный канал — сарафанное радио. Почти 60% узнали о городе от знакомых и родственников. На втором месте — соцсети и интернет, около 19%. А вот новости по телевизору и официальные сайты почти не работают. Фильмы и сериалы — тем более.',
        'Вывод простой: если хочешь, чтобы о тебе знали правду, не вкладывай деньги в отчёты. Вкладывай в реальных людей и хороший контент для тиктоков. Один студент, который честно скажет «Тюмень — это чисто», убедит десятерых друзей. Одно красивое видео с набережной — сотни просмотров.'
      ],
      conclusion: 'Стереотипы о Тюмени живучи, но они слабеют. Реальность оказывается сильнее. Мы это проверили на 137 иностранцах и готовы спорить на что угодно — приезжайте и сами увидите.',
      studentsText: 'студентов',
      donutLegend: [
        { label: 'Сарафанное радио', value: 58.8, color: '#00a0e3' },
        { label: 'Интернет / соцсети', value: 19.5, color: '#4dc0ee' },
        { label: 'Сериалы и фильмы', value: 12.3, color: '#87d8f5' },
        { label: 'Другое', value: 9.4, color: '#39538A' }
      ]
    },
    EN: {
      title: 'About the Project / Research',
      intro: [
        'We are students of Tyumen State University. And we decided to figure out what foreign students actually think about Tyumen.',
        'Why do we need this? First, it\'s interesting. Second, stereotypes about Siberia are no joke. "It\'s cold, dangerous, nothing to do there" — such thoughts really prevent people from coming here. This means the country loses talented youth, and foreigners limit themselves from visiting a good city.',
        'We surveyed 137 international students of our university. From Kazakhstan, Uzbekistan, Greece, Azerbaijan, China, and other countries. We asked: what did they know before arriving, what were they afraid of, what did they actually see, and would they recommend it to friends.',
        'The questionnaire was not just with checkboxes, but with open-ended questions. That is why we have many lively quotes, sometimes funny, sometimes very honest. Someone wrote about the "capital of villages", someone - "open people", and one guy from Kazakhstan asked: "Will I get a point for my organization grade for answering?"'
      ],
      findingsTitle: 'What we found out',
      findings: [
        'The main figure is 80%. This is the percentage of respondents who said their expectations of Tyumen were met or exceeded. In sociology, this is a very strong result.',
        'Before arriving, almost no one knew anything about the history and architecture of the city. Even the fact that Lenin once lay here is known to few. Instead of facts, there are stereotypes: severe cold, remote village, angry people.',
        'Most of all, they were afraid of the cold. "Damn, it\'s -40 there, I\'ll freeze" — they wrote exactly like that. They were also afraid that they would not be accepted, that there would be problems with the dorm and documents.',
        'But it turned out that the city is modern and clean. The embankment, good roads, beautiful buildings. People are open and helpful. Even the climate did not disappoint: the average temperature in winter is about -17, not -40. And in summer it is quite +25.',
        'If you dig deeper, you can see three completely different types of students.'
      ],
      types: [
        { title: 'Kazakhstanis (55 people)', desc: 'The calmest and most adapted group. They arrive without culture shock, the main thing for them is cleanliness and order. In Tyumen, they find what they are looking for.' },
        { title: 'Uzbekistanis (24 people)', desc: 'Most often they go to relatives. For them, Tyumen is about money, work, and expensive documents. They need specific help: with housing, registration, money.' },
        { title: 'Europe & Muscovites (58 people)', desc: 'They bring with them the stereotype of a "village". At first, they look down, and then they are sincerely surprised that Tyumen is a normal modern city. They need to be shown architecture, culture, normal city life. Personal experience works with them, not statistics.' }
      ],
      donutTitle: 'Where do they learn about Tyumen',
      donutText: [
        'The most important channel is word of mouth. Almost 60% learned about the city from friends and relatives. In second place — social networks and the Internet, about 19%. But news on TV and official websites almost don\'t work. Movies and TV series — even less so.',
        'The conclusion is simple: if you want the truth to be known about you, do not invest money in reports. Invest in real people and good content for TikToks. One student who honestly says "Tyumen is clean" will convince ten friends. One beautiful video from the embankment — hundreds of views.'
      ],
      conclusion: 'Stereotypes about Tyumen are persistent, but they are weakening. Reality turns out to be stronger. We checked this on 137 foreigners and are ready to bet on anything — come and see for yourself.',
      studentsText: 'students',
      donutLegend: [
        { label: 'Word of mouth', value: 58.8, color: '#00a0e3' },
        { label: 'Internet / Social media', value: 19.5, color: '#4dc0ee' },
        { label: 'TV Shows & Movies', value: 12.3, color: '#87d8f5' },
        { label: 'Other', value: 9.4, color: '#39538A' }
      ]
    }
  };

  const currentData = content[language];

  useEffect(() => {
    let hasAnimated = false; 
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !hasAnimated) {
          setAnimateCharts(true);
          setAnimateDonut(true);
          hasAnimated = true;
          observer.disconnect(); 
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) observer.observe(sectionRef.current);
    
    return () => {
      observer.disconnect();
      setAnimateCharts(false);
      setAnimateDonut(false);
    };
  }, []);

  useEffect(() => {
    if (animateDonut) {
      const animateSegments = () => {
        const segments = document.querySelectorAll('.donut-segment');
        const circumference = 502;
        segments.forEach(segment => {
          const value = parseFloat(segment.getAttribute('data-value'));
          const dashArray = (value / 100) * circumference;
          segment.style.transition = 'stroke-dasharray 1.5s cubic-bezier(0.4, 0, 0.2, 1)';
          segment.style.strokeDasharray = `${dashArray} ${circumference}`;
        });
      };
      animateSegments();
    }
  }, [animateDonut]);

  return (
    <section id="research" ref={sectionRef} className="research section">
      <div className="container">
        <h2 className="section-title">{currentData.title}</h2>
        
        <div className="research-intro">
          {currentData.intro.map((p, i) => (
            <p key={i}>{p}</p>
          ))}
        </div>

        <div className="research-text-block-centered">
          <h3>{currentData.findingsTitle}</h3>
          {currentData.findings.map((p, i) => (
            <p key={i}>{p}</p>
          ))}
        </div>

        <div className="student-types-grid">
          {currentData.types.map((type, i) => (
            <div className="student-card" key={i}>
              <h4>{type.title}</h4>
              <p>{type.desc}</p>
            </div>
          ))}
        </div>

        <div className="donut-container">
          <img src={`${publicUrl}/images/kotak_research.webp`} alt="Котеус статистика" className="cat-research" loading="lazy" />
          
          <div className="donut-layout">
            <div className="donut-text">
              <h3>{currentData.donutTitle}</h3>
              {currentData.donutText.map((p, i) => (
                <p key={i}>{p}</p>
              ))}
            </div>
            
            <div className="donut-chart-wrapper">
              <div className="donut-chart">
                <svg viewBox="0 0 200 200" className="donut-svg">
                  <circle cx="100" cy="100" r="80" fill="none" stroke="var(--bg-secondary)" strokeWidth="24"/>
                  <circle cx="100" cy="100" r="80" fill="none" stroke="#00a0e3" strokeWidth="24" strokeDasharray="0 502" transform="rotate(-90 100 100)" className="donut-segment" data-value="58.8" />
                  <circle cx="100" cy="100" r="80" fill="none" stroke="#4dc0ee" strokeWidth="24" strokeDasharray="0 502" transform="rotate(-90 100 100)" className="donut-segment" data-value="19.5" />
                  <circle cx="100" cy="100" r="80" fill="none" stroke="#87d8f5" strokeWidth="24" strokeDasharray="0 502" transform="rotate(-90 100 100)" className="donut-segment" data-value="12.3" />
                  <circle cx="100" cy="100" r="80" fill="none" stroke="#39538A" strokeWidth="24" strokeDasharray="0 502" transform="rotate(-90 100 100)" className="donut-segment" data-value="9.4" />
                </svg>
                <div className="donut-center-text">
                  <span className="donut-number">
                    <AnimatedCounter targetValue={137} suffix="" duration={1200} startDelay={300} isActive={animateCharts} />
                  </span>
                  <span className="donut-label">{currentData.studentsText}</span>
                </div>
              </div>
              <div className="donut-legend">
                {currentData.donutLegend.map((item, idx) => (
                  <div key={idx} className="legend-item">
                    <span className="legend-color" style={{ backgroundColor: item.color }}></span>
                    <span className="legend-text">{item.label} — <strong>{item.value}%</strong></span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        <p className="research-conclusion">{currentData.conclusion}</p>

      </div>
    </section>
  );
};

export default Research;